from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal('0.01')
RATE_QUANTUM = Decimal('0.0001')

BRACKETS = [
    # (upper bound inclusive, marginal rate)
    (Decimal('10000'), Decimal('0.10')),
    (Decimal('40000'), Decimal('0.22')),
    (None, Decimal('0.35')),  # top bracket: no upper bound
]


def _validate(income):
    if income < 0:
        raise ValueError("income must be non-negative")
    return income


def tax_due(income):
    """Total tax owed on `income`, rounded to the cent."""
    _validate(income)
    tax = Decimal('0')
    lower = Decimal('0')
    for upper, rate in BRACKETS:
        if upper is not None and income > upper:
            portion = upper - lower
        else:
            portion = income - lower
            tax += portion * rate
            break
        tax += portion * rate
        lower = upper
    return (tax).quantize(CENT, rounding=ROUND_HALF_UP)


def marginal_rate(income):
    """The rate applied to the next unit of income."""
    _validate(income)
    for upper, rate in BRACKETS:
        if upper is None or income < upper:
            return rate.quantize(Decimal('0.01'))
    # income exactly at a boundary belongs to the lower bracket's ceiling,
    # so the next unit falls into the following bracket — handled above.
    raise AssertionError("unreachable")


def effective_rate(income):
    """Average tax rate: total tax divided by income, 4 decimal places."""
    _validate(income)
    if income == 0:
        return Decimal('0.0000')
    return (tax_due(income) / income).quantize(RATE_QUANTUM, rounding=ROUND_HALF_UP)

